import './App.css';
import Menu from './comPoNent/Menu';
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import "./comPoNent/GioHang/Cart"
import { CartProvider } from "./comPoNent/GioHang/CartContext";
function App() {
  return (
      <Router>
          <Menu />
          <Routes>

              <CartProvider>
                  <div className="Tong"  style={{ padding: "40px" }}>
                      <h1 className="header"> Shopping Cart</h1>
                      <ProductList />
                      <Cart />
                  </div>
              </CartProvider>

          </Routes>
      </Router>
  );
}

export default App;
